19	std::vector<DeviceDriver *> DeviceDriver::getDrivers()
20	{
21	    static std::vector<DeviceDriver*> ret;
22	    if (ret.size() == 0) {
23	        // first function call
24	        ret.push_back(new LibreVNAUSBDriver);
25	        ret.push_back(new LibreVNATCPDriver);
26	        ret.push_back(new CompoundDriver);
27	        ret.push_back(new SSA3000XDriver);
28	        ret.push_back(new SNA5000ADriver);
